{"Channel": {"name": "planning-ContentRecommender", "channelID": "ch-ender-33b51f"}, "Message": {"User": {"userId": "eid_c0df5be6", "timestamp": "2026-03-04T00:55:00", "text": "Hi team, I want to discuss our upcoming Product Vision Document for ContentRecommender. Let's brainstorm some ideas! 😊", "utterranceID": "20260303-0-73f17"}, "Reactions": []}, "ThreadReplies": [], "id": "20260303-0-73f17"}
