{"Channel": {"name": "bug-juliamartinez-EdgeForce", "channelID": "ch-force-7bfbef"}, "Message": {"User": {"userId": "eid_91523bad", "timestamp": "2026-12-27T15:58:00", "text": "First up, we have a 'Data Corruption During Model Update' issue. This is affecting the Model Management & Update Module. Customers are experiencing data corruption during AI model updates, leading to incorrect outputs. This is impacting CUST-0066. @eid_2347b567, can you take this one?", "utterranceID": "20261227-1-a0f8d"}, "Reactions": []}, "ThreadReplies": [], "id": "20261227-1-a0f8d"}
