{"Channel": {"name": "bug-juliamartinez-EdgeForce", "channelID": "ch-force-7bfbef"}, "Message": {"User": {"userId": "eid_2347b567", "timestamp": "2026-12-27T16:18:00", "text": "Thanks for the heads-up, @eid_91523bad. I'll reach out if I need anything. Let's get these issues sorted! 😊", "utterranceID": "20261227-8-a8d0c"}, "Reactions": []}, "ThreadReplies": [], "id": "20261227-8-a8d0c"}
