{"Channel": {"name": "bug-juliataylor-TrendForce", "channelID": "ch-force-504165"}, "Message": {"User": {"userId": "eid_2542cff3", "timestamp": "2026-08-04T13:17:00", "text": "I'll keep you all updated on the bottleneck issue. Let's get these sorted for our customers! 💪", "utterranceID": "20260804-10-a3051"}, "Reactions": []}, "ThreadReplies": [], "id": "20260804-10-a3051"}
