{"Channel": {"name": "develop-ianjones-LeadForce", "channelID": "ch-s-aix-1f811d"}, "Message": {"User": {"userId": "eid_f98d7490", "timestamp": "2026-05-01T08:55:00", "text": "Hi team, I came across some interesting open-source features that might give us some insights for our Lead Scoring data structures. Let's discuss them! 😊", "utterranceID": "20260430-0-182ba"}, "Reactions": []}, "ThreadReplies": [], "id": "20260430-0-182ba"}
