{"Channel": {"name": "develop-ianjones-LeadForce", "channelID": "ch-s-aix-1f811d"}, "Message": {"User": {"userId": "eid_b814ccfb", "timestamp": "2026-06-29T19:44:00", "text": "The bugs are causing some lead engagement events to not be published correctly. It's affecting our data pipeline significantly.", "utterranceID": "20260629-2-2b49c"}, "Reactions": []}, "ThreadReplies": [], "id": "20260629-2-2b49c"}
{"Channel": {"name": "develop-ianjones-LeadForce", "channelID": "ch-s-aix-1f811d"}, "Message": {"User": {"userId": "eid_7b85a749", "timestamp": "2026-06-29T19:47:00", "text": "Do we have any logs or error messages that could help us pinpoint the issue?", "utterranceID": "20260629-3-26d04"}, "Reactions": []}, "ThreadReplies": [], "id": "20260629-3-26d04"}
{"Channel": {"name": "develop-ianjones-LeadForce", "channelID": "ch-s-aix-1f811d"}, "Message": {"User": {"userId": "eid_88e74382", "timestamp": "2026-06-29T19:49:00", "text": "I checked the logs, and it seems like there's a problem with the message serialization process. It's causing some messages to be dropped.", "utterranceID": "20260629-4-da0ae"}, "Reactions": []}, "ThreadReplies": [], "id": "20260629-4-da0ae"}
{"Channel": {"name": "develop-ianjones-LeadForce", "channelID": "ch-s-aix-1f811d"}, "Message": {"User": {"userId": "eid_c39dc658", "timestamp": "2026-06-29T19:54:00", "text": "Thanks for the info. @eid_652e8cd0, can you provide any insights on the serialization logic? Was there any recent change that might have caused this?", "utterranceID": "20260629-5-4a5b7"}, "Reactions": []}, "ThreadReplies": [], "id": "20260629-5-4a5b7"}

